import{_ as e,o as a,c as s,a5 as r}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"当前传输方式与平台限制","description":"","frontmatter":{"title":"当前传输方式与平台限制","docId":"developer.transports","translationKey":"developer.transports","locale":"zh","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","translationRevision":"170fec34f0552f33947038429c504c2ca8720074fc76079eb61b3848439f4897","order":200},"headers":[],"relativePath":"zh/developer/transports.md","filePath":"zh/developer/transports.md","lastUpdated":1794611623000}'),i={name:"zh/developer/transports.md"};function o(d,t,n,l,h,p){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">当前传输方式与平台限制 <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;当前传输方式与平台限制 {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>选择目标构建和平台上实际存在的传输方式。先阅读 <a href="./control-api.html">Control API</a> 和<a href="./collaboration.html">协作</a>。传输负责承载序列化操作，不能引入第二个核心，也不能自行授予权限。</p><h2 id="choose-the-boundary" tabindex="-1">选择边界 <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;选择边界 {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>当前实现</th><th>重要限制</th></tr></thead><tbody><tr><td>桌面 WebView</td><td>Wry IPC 与共享控制客户端</td><td>GUI/线程生命周期属于桌面</td></tr><tr><td>本地 CLI</td><td>Unix 套接字或 Windows 命名管道；明确的 stdio 宿主</td><td>使用同一应用主目录及所有者</td></tr><tr><td>本地浏览器</td><td>原生回环适配器及 <code>browser-transport.ts</code></td><td>配对的原生宿主，并非模拟对象或公开远程服务器</td></tr><tr><td>直接远程</td><td>经身份验证的 HTTPS/WSS 网关及 SDK/浏览器传输</td><td>TLS、hello、授权与功能门控</td></tr><tr><td>原生对等连接</td><td><code>tiktools-peer</code>，加密 iroh/QUIC 流</td><td>对等身份不等于 RPC 权限</td></tr><tr><td>原生 WebRTC</td><td><code>tiktools-rtc</code>，签名信令与数据通道</td><td>仍须进行协商、授权与路由检查</td></tr></tbody></table><p>TypeScript 传输接口位于 <code>src/web/shared/api/control-transport.ts</code>。原生对等配置不会隐式启用公开第三方中继或发现。WebRTC 是原生 Rust 实现（<code>webrtc</code> 0.21.1），不依赖桌面 UI 中的浏览器 <code>RTCPeerConnection</code>。</p><h2 id="inspect-the-selected-route" tabindex="-1">检查选定路由 <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;检查选定路由 {#inspect-the-selected-route}&quot;">​</a></h2><p>配对或显示控制端操作前，先发现所连宿主支持的方法与能力：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-browser-transport</span></span></code></pre></div><p><code>tiktools-rtc/src/route.rs</code> 观察选定的 ICE 候选对，以区分直连与中继。仅有就绪状态不能证明是直连。Cloud 信令/中继连接机制与业务授权相互独立，必须保留原生授权检查。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>本地 IPC 和桌面传输是成熟路径。原生对等、WebRTC 和控制端集成已有源码及针对性测试，但部署与多电脑验收仍属实验性。旧文档声称没有对等/中继实现的内容已属历史。Android 本地 IPC 可用；持久化远程配置尚未选定凭据存储，桌面原生扩展和 WebView 在该平台仍不可用。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>断线后，应将已接受操作视为可能存在不确定结果。重连必须使私有投影失效、重新协商身份，并恢复有界流或获取快照。不要降低证书检查要求，也不要在远程失败后静默回退到本地所有者。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-rtc/src" target="_blank" rel="noreferrer">RTC 实现</a>及实际功能依赖图优先于旧传输计划。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>Peer 使用 ALPN <code>tiktools/collaboration/1</code>，当前连接超时为 15 秒，最多显式配置四个 relay。Peer/RTC 帧上限为 1 MiB；RTC 拆分为最多 16 KiB 的数据包。超大帧会在验证中失败，不产生部分 RPC。应分别诊断配置/身份、信令、连接超时、帧大小及授权。Cloud relay 不是 ICE TURN 服务器；空 relay 列表不启用公共发现。测试路径前检查宿主/设备活动及当前已确认授权，并记录 ICE 选择直连还是 relay。ready/加密传输不证明 RPC 权限，也不保证穿越所有 NAT。真实双机验收前，用 fixtures 测试会话变化/撤销和超大帧。</p>`,16)])])}const u=e(i,[["render",o]]);export{k as __pageData,u as default};
